        expectArchivedAs(onlyArchiveOf(h.database, REFUND_PATH), refundBody(kept, options));
        expectAskedOnce(
          own.reader,
          built.flatMap((entry) => (entry.no === null ? [] : [entry.no])),
        );
      }),
      propParams(),
    ),
  ).resolves.toBeUndefined();
}, 900_000);

